def compute(vars):
    margin_2015 = vars["v1"]
    margin_2016 = vars["v2"]
    increase = margin_2016 - margin_2015

    return {
        "value": increase,
        "trace": {
            "margin_2015": margin_2015,
            "margin_2016": margin_2016,
            "increase": increase,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
